insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('portfolio-media','portfolio-media',true,15728640,array['image/jpeg','image/png','image/webp','image/avif','application/pdf','video/mp4']) on conflict(id) do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy media_public_read on storage.objects for select to public using(bucket_id='portfolio-media');
